def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    objects = []
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y),
                               (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))

            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)
            side = r1 - r0 + 1

            if side < 3 or c1 - c0 + 1 != side:
                continue
            if not all(grid[x][y] in (color, bg)
                       for x in range(r0, r1 + 1)
                       for y in range(c0, c1 + 1)):
                continue

            # Count 4-connected components of background-colored holes
            # inside this square patch.
            hole_seen = set()
            hole_components = 0
            for x in range(r0, r1 + 1):
                for y in range(c0, c1 + 1):
                    if grid[x][y] != bg or (x, y) in hole_seen:
                        continue
                    hole_components += 1
                    hole_seen.add((x, y))
                    q = deque([(x, y)])
                    while q:
                        a, b = q.popleft()
                        for na, nb in ((a - 1, b), (a + 1, b),
                                       (a, b - 1), (a, b + 1)):
                            if (r0 <= na <= r1 and c0 <= nb <= c1 and
                                    grid[na][nb] == bg and
                                    (na, nb) not in hole_seen):
                                hole_seen.add((na, nb))
                                q.append((na, nb))

            objects.append({
                "r": r0, "c": c0, "side": side,
                "color": color, "holes": hole_components
            })

    size_counts = Counter(obj["side"] for obj in objects)
    possible = [n for n in size_counts if n + 2 in size_counts]
    if not possible:
        return [row[:] for row in grid]

    n = max(possible, key=lambda x: (
        min(size_counts[x], size_counts[x + 2]),
        size_counts[x] + size_counts[x + 2],
        -x
    ))
    side = n + 2
    frames = [obj for obj in objects if obj["side"] == side]
    patterns = [obj for obj in objects if obj["side"] == n]

    def make_groups(values):
        groups = []
        for value in sorted(values):
            if not groups or value - groups[-1][0] >= side:
                groups.append([value])
            else:
                groups[-1].append(value)
        return groups

    row_groups = make_groups([obj["r"] for obj in frames])
    col_groups = make_groups([obj["c"] for obj in frames])

    def group_index(value, groups):
        return min(range(len(groups)), key=lambda i: abs(value - groups[i][0]))

    frames.sort(key=lambda obj: (
        group_index(obj["r"], row_groups),
        group_index(obj["c"], col_groups),
        obj["r"], obj["c"]
    ))

    remaining = patterns[:]
    paired = []
    for frame in frames:
        if not remaining:
            break
        matching = [p for p in remaining if p["holes"] == frame["holes"]]
        choices = matching if matching else remaining
        pattern = min(choices, key=lambda p: (
            abs(p["r"] - frame["r"]) + abs(p["c"] - frame["c"])
        ))
        remaining.remove(pattern)
        paired.append((frame, pattern))

    out = [[0] * (len(col_groups) * side)
           for _ in range(len(row_groups) * side)]

    for frame, pattern in paired:
        ri = group_index(frame["r"], row_groups)
        ci = group_index(frame["c"], col_groups)
        rbase, cbase = ri * side, ci * side

        for i in range(side):
            for j in range(side):
                if 0 < i < side - 1 and 0 < j < side - 1:
                    value = grid[pattern["r"] + i - 1][pattern["c"] + j - 1]
                    out[rbase + i][cbase + j] = (
                        pattern["color"] if value == pattern["color"]
                        else frame["color"]
                    )
                else:
                    out[rbase + i][cbase + j] = frame["color"]

    return out
